def self.dump_http_json_record(record, dump_proc, newline = nil)
  dumped = dump_proc.call(record)
  if newline.nil? || newline == false
    dumped
  else
    "#{dumped}#{newline}"
  end
end

def self.http_json_media_type(json_array = false)
  if json_array
    "application/json"
  else
    "application/x-ndjson"
  end
end

def self.each_http_msgpack_object(unpacker, data)
  unpacker.feed_each(data) do |obj|
    yield obj
  end
end

def self.each_http_msgpack_io(io)
  unpacker = Fluent::MessagePackFactory.engine_factory.unpacker(io)
  unpacker.each do |obj|
    yield obj
  end
end

def self.align_http_json_time(time, utc_offset)
  return time if time.nil?
  return time if utc_offset.nil? || utc_offset == 0
  time
end

private

def on_server_connect(conn)
  handler = Handler.new(conn, @km, method(:on_request),
                        @body_size_limit, @format_name, log,
                        @cors_allow_origins, @cors_allow_credentials,
                        @add_query_params)

  conn.on(:data) do |data|
    handler.on_read(data)
  end

  conn.on(:write_complete) do |_|
    handler.on_write_complete
  end

  conn.on(:close) do |_|
    handler.on_close
  end
end

def parse_params_default(params)
  if msgpack = params['msgpack']
    @parser_msgpack.parse(msgpack) do |_time, record|
      return nil, record
    end
  elsif js = params['json']
    @parser_json.parse(js) do |_time, record|
      return nil, record
    end
  else
    raise "'json' or 'msgpack' parameter is required"
  end
end

def parse_params_with_parser(params)
  if content = params[EVENT_RECORD_PARAMETER]
    @custom_parser.parse(content) { |time, record|
      raise "Received event is not #{@format_name}: #{content}" if record.nil?
      return time, record
    }
  else
    raise "'#{EVENT_RECORD_PARAMETER}' parameter is required"
  end
end

def add_params_to_record(record, params)
  merge_http_headers_into_record(record, params)
  merge_http_query_into_record(record, params)
  merge_http_remote_into_record(record, params)
  record
end

def convert_time_field(record)
  if t = @default_keep_time_key ? record[@parser_time_key] : record.delete(@parser_time_key)
    if @default_time_parser
      @default_time_parser.parse(t)
    else
      Fluent::EventTime.from_time(Time.at(t))
    end
  else
    Fluent::EventTime.now
  end
end

class Handler
  attr_reader :content_type

  def initialize(io, km, callback, body_size_limit, format_name, log,
                 cors_allow_origins, cors_allow_credentials, add_query_params)
    @io = io
    @km = km
    @callback = callback
    @body_size_limit = body_size_limit
    @next_close = false
    @format_name = format_name
    @log = log
    @cors_allow_origins = cors_allow_origins
    @cors_allow_credentials = cors_allow_credentials
    @idle = 0
    @add_query_params = add_query_params
    @km.add(self)

    @remote_port, @remote_addr = io.remote_port, io.remote_addr
    @parser = Http::Parser.new(self)
    @input = callback.receiver if callback.respond_to?(:receiver)
  end

  def step_idle
    @idle += 1
  end

  def on_close
    @km.delete(self)
  end

  def on_read(data)
    @idle = 0
    @parser << data
  rescue
    @log.warn "unexpected error", error: $!.to_s
    @log.warn_backtrace
    @io.close
  end

  def on_message_begin
    @body = ''
  end

  def on_headers_complete(headers)
    expect = nil
    size = nil

    if @parser.http_version == [1, 1]
      @keep_alive = true
    else
      @keep_alive = false
    end
    @env = {}
    @content_type = ""
    @content_encoding = ""
    headers.each_pair {|k,v|
      @env["HTTP_#{k.gsub('-','_').upcase}"] = v
      case k
      when /\AExpect\z/i
        expect = v
      when /\AContent-Length\Z/i
        size = v.to_i
      when /\AContent-Type\Z/i
        @content_type = v

